const items = $input.all();

return items.map((item) => {
  const input = item.json ?? {};

  // Support both raw chat output and already-parsed JSON.
  let parsed;
  const text =
    input.content?.parts?.[0]?.text ??
    input.output?.content?.parts?.[0]?.text ??
    input.text ??
    null;

  if (typeof text === "string" && text.trim()) {
    try {
      parsed = JSON.parse(
        text.replace(/^```json\s*/i, "").replace(/\s*```$/, "").trim()
      );
    } catch (error) {
      return {
        json: {
          parse_error: true,
          message: "Requirement Analysis text is not valid JSON.",
          raw_text: text,
        },
      };
    }
  } else if (typeof input.request_topic === "string") {
    parsed = input;
  } else {
    return {
      json: {
        parse_error: true,
        message: "Requirement Analysis output was not found in the expected fields.",
        incoming_data: input,
      },
    };
  }

  return {
    json: {
      request_topic: String(parsed.request_topic ?? "").trim(),
      requirement_summary: String(parsed.requirement_summary ?? "").trim(),
      domain: String(parsed.domain ?? "").trim(),
      industry: String(parsed.industry ?? "").trim(),
      entities: Array.isArray(parsed.entities) ? parsed.entities : [],
      required_fields: Array.isArray(parsed.required_fields)
        ? parsed.required_fields
        : [],
      relationships: Array.isArray(parsed.relationships)
        ? parsed.relationships
        : [],
      time_period: String(parsed.time_period ?? "").trim(),
      data_volume: String(parsed.data_volume ?? "").trim(),
      business_rules: Array.isArray(parsed.business_rules)
        ? parsed.business_rules
        : [],
      required_datasets: Array.isArray(parsed.required_datasets)
        ? parsed.required_datasets
        : [],
      csv_requirements: String(parsed.csv_requirements ?? "").trim(),
    },
  };
});

const items = $input.all();

const allResults = [];

for (const item of items) {
  const data = item.json || {};

  const requestTopic = String(
    data.request_topic || ""
  ).trim();

  const searchQuery = String(
    data.query || ""
  ).trim();

  const results = Array.isArray(data.results)
    ? data.results
    : [];

  for (const r of results) {
    const sourceUrl = String(
      r.url || ""
    ).trim();

    if (!sourceUrl) {
      continue;
    }

    const lowerUrl = sourceUrl.toLowerCase();

    let platform = "other";

    if (lowerUrl.includes("huggingface.co")) {
      platform = "huggingface.co";
    }
    else if (lowerUrl.includes("kaggle.com")) {
      platform = "kaggle.com";
    }
    else if (lowerUrl.includes("github.com")) {
      platform = "github.com";
    }
    else if (lowerUrl.includes("zenodo.org")) {
      platform = "zenodo.org";
    }

    allResults.push({
      request_topic: requestTopic,
      platform: platform,
      source_title: String(
        r.title || ""
      ).trim(),
      source_url: sourceUrl,
      source_content: String(
        r.content || ""
      ).trim(),
      search_query: searchQuery
    });
  }
}

return [
  {
    json: {
      request_topic: String(
        allResults[0]?.request_topic || ""
      ).trim(),

      total_results: allResults.length,

      results: allResults
    }
