const input = $input.first().json || {};

const requestTopic = String(
  input.request_topic || ""
).trim();

const results = Array.isArray(input.results)
  ? input.results
  : [];

const output = [];

for (const data of results) {

  const sourceUrl = String(
    data.source_url || ""
  ).trim();

  const platform = String(
    data.platform || ""
  ).trim().toLowerCase();

  const sourceTitle = String(
    data.source_title || ""
  ).trim();

  if (!sourceUrl || !platform) {
    continue;
  }

  let apiUrl = "";

  // -----------------------------
  // HUGGING FACE
  // -----------------------------
  if (platform === "huggingface.co") {

    const match = sourceUrl.match(
      /huggingface\.co\/datasets\/([^/?#]+\/[^/?#]+)/i
    );

    if (match) {
      apiUrl =
        `https://huggingface.co/api/datasets/${match[1]}`;
    }
  }

  // -----------------------------
  // KAGGLE
  // -----------------------------
  else if (platform === "kaggle.com") {

    const match = sourceUrl.match(
      /kaggle\.com\/datasets\/([^/]+)\/([^/?#]+)/i
    );

    if (match) {
      apiUrl =
        `https://www.kaggle.com/api/v1/datasets/view/${match[1]}/${match[2]}`;
    }
  }

  // -----------------------------
  // GITHUB
  // -----------------------------
  else if (platform === "github.com") {

    // Ignore GitHub topic/search pages
    if (!sourceUrl.includes("/topics/")) {

      const match = sourceUrl.match(
        /github\.com\/([^/]+)\/([^/?#]+)/i
      );

      if (match) {
        apiUrl =
          `https://api.github.com/repos/${match[1]}/${match[2]}/git/trees/HEAD?recursive=1`;
      }
    }
  }

  // -----------------------------
  // ZENODO
  // -----------------------------
  else if (platform === "zenodo.org") {

    const match = sourceUrl.match(
      /zenodo\.org\/records\/([^/?#]+)/i
    );

    if (match) {
      apiUrl =
        `https://zenodo.org/api/records/${match[1]}`;
    }
  }

  output.push({
    request_topic: requestTopic,
    platform: platform,
    source_title: sourceTitle,
    source_url: sourceUrl,
    api_url: apiUrl,
    api_url_found: apiUrl !== ""
  });
}

// Keep everything as ONE output item
return [
  {
    json: {
      request_topic: requestTopic,
      total_sources: output.length,
      sources: output
    }
  }
];

