const allowedExtensions = [
  ".csv",
  ".pdf",
  ".doc",
  ".docx",
  ".xls",
  ".xlsx",
  ".txt",
  ".zip"
];

const files = [];

let requestTopic = "";

for (const item of items) {
  const data = item.json || {};

  // Preserve dynamic request topic
  if (!requestTopic) {
    requestTopic = String(
      data.request_topic || ""
    ).trim();
  }

  const body = data.body || {};

  const tree = Array.isArray(body.tree)
    ? body.tree
    : [];

  // Get repository owner/name from the API URL
  const apiUrl = String(
    body.url || ""
  ).trim();

  const repoMatch = apiUrl.match(
    /api\.github\.com\/repos\/([^/]+\/[^/]+)\/git\/trees/i
  );

  const repository = repoMatch
    ? repoMatch[1]
    : "";

  for (const file of tree) {
    const filename = String(
      file.path || ""
    ).trim();

    if (!filename) {
      continue;
    }

    // Only process actual files, not folders
    if (file.type !== "blob") {
      continue;
    }

    const lowerFilename = filename.toLowerCase();

    if (
      !allowedExtensions.some(ext =>
        lowerFilename.endsWith(ext)
      )
    ) {
      continue;
    }

    files.push({
      platform: "github.com",
      repository: repository,
      filename: filename,
      file_type:
        filename
          .substring(filename.lastIndexOf(".") + 1)
          .toLowerCase(),
      file_url:
        `https://raw.githubusercontent.com/${repository}/HEAD/${filename}`
    });
  }
}

if (!requestTopic) {
  try {
    requestTopic = String($node["code.execute-1791438368178001"]?.json?.request_topic || $node["code.execute-1791355811168006"]?.json?.request_topic || $node["webhook-1791618803607002"]?.json?.body?.topic || "").trim();
