const items = $input.all();

const files = [];

let requestTopic = "";

for (const item of items) {

  const data = item.json || {};

  // Get topic if it has been passed through the extract nodes
  if (!requestTopic) {
    requestTopic = String(
      data.request_topic || ""
    ).trim();
  }


  // ==========================================================
  // Hugging Face / GitHub / Zenodo
  // ==========================================================

  if (Array.isArray(data.files)) {

    for (const file of data.files) {

      const platform = String(
        file.platform ||
        data.platform ||
        ""
      ).trim().toLowerCase();

      const filename = String(
        file.filename ||
        file.name ||
        ""
      ).trim();

      const downloadUrl = String(
        file.file_url ||
        file.download_url ||
        ""
      ).trim();

      if (!platform || !filename || !downloadUrl) {
        continue;
      }

      let datasetName = "";

      if (platform === "huggingface.co") {

        datasetName = String(
          file.dataset_id ||
          data.dataset_id ||
          file.dataset_name ||
          data.dataset_name ||
          ""
        ).trim();

      } else if (platform === "github.com") {

        datasetName = String(
          file.repository ||
          data.repository ||
          file.dataset_name ||
          data.dataset_name ||
          ""
        ).trim();

      } else if (platform === "zenodo.org") {

        datasetName = String(
          file.dataset_title ||
          data.dataset_title ||
          file.dataset_name ||
          data.dataset_name ||
          ""
        ).trim();
      }

      files.push({
        request_topic: requestTopic,
        platform: platform,
        dataset_name: datasetName,

        source_url: String(
          file.source_url ||
          data.source_url ||
          ""
        ).trim(),

        download_url: downloadUrl,

        filename: filename,

        file_type: String(
          file.file_type ||
          filename.split(".").pop() ||
          ""
        ).trim().toLowerCase()
      });
    }
  }


  // ==========================================================
  // Kaggle
  // ==========================================================

  if (Array.isArray(data.datasets)) {

    for (const dataset of data.datasets) {

      const datasetName = String(
        dataset.title ||
        dataset.dataset_ref ||
        ""
      ).trim();

      const downloadUrl = String(
        dataset.download_url ||
        ""
      ).trim();

      if (!downloadUrl) {
        continue;
      }

      files.push({
        request_topic: requestTopic,
        platform: "kaggle.com",
        dataset_name: datasetName,

        source_url: String(
          dataset.source_url ||
          data.source_url ||
          ""
        ).trim(),

        download_url: downloadUrl,

        filename:
          datasetName
            ? `${datasetName}.zip`
            : "dataset.zip",

        file_type: "zip"
      });
    }
  }
}


