return items.map(item => {
  const data = item.json || {};
  let requestTopic = upstreamTopic;

  if (!requestTopic) {
    const rawMsg = String(
      data.query || data.message || ''
    ).trim();
    const lowerMsg = rawMsg.toLowerCase();

    if (
      lowerMsg.includes('insurance') ||
      lowerMsg.includes('claim') ||
      lowerMsg.includes('premium') ||
      lowerMsg.includes('policy')
    ) {
      requestTopic = 'Insurance';
    } else if (
      lowerMsg.includes('procurement') ||
      lowerMsg.includes('purchase order') ||
      lowerMsg.includes('supplier') ||
      lowerMsg.includes('vendor')
    ) {
      requestTopic = 'Procurement';
    } else if (
      lowerMsg.includes('supply chain') ||
      lowerMsg.includes('logistics') ||
      lowerMsg.includes('shipment') ||
      lowerMsg.includes('warehouse')
    ) {
      requestTopic = 'Supply Chain';
    } else if (
      lowerMsg.includes('health') ||
      lowerMsg.includes('hospital') ||
      lowerMsg.includes('patient')
    ) {
      requestTopic = 'Healthcare';
    } else if (
      lowerMsg.includes('finance') ||
      lowerMsg.includes('financial') ||
      lowerMsg.includes('revenue') ||
      lowerMsg.includes('banking')
    ) {
      requestTopic = 'Finance';
    } else if (
      lowerMsg.includes('e-commerce') ||
      lowerMsg.includes('ecommerce') ||
      lowerMsg.includes('retail')
    ) {
      requestTopic = 'E-Commerce';
    } else if (rawMsg) {
      const words = rawMsg.replace(/^(find|datasets?|for|about|containing)\\s+/i, '').split(/\\s+/).slice(0, 3).join(' ');
      requestTopic = words ? words.charAt(0).toUpperCase() + words.slice(1) : '';
    }
  }

  return {
    json: {
      ...data,
      request_topic: requestTopic
    }
  };
});

